using System.Security.Cryptography;
using System.Text;

namespace Ares.Identity.Auth;

/// <summary>
/// API-key hashing and verification.
///
/// Rationale: platform API keys are 256-bit random secrets generated by
/// <see cref="GenerateKey"/>, so a single SHA-256 is sufficient (no brute-force
/// surface, unlike low-entropy passwords that need a KDF). The optional pepper
/// prevents a stolen database from being replayed against another deployment.
/// Comparison is constant-time and never short-circuits.
/// </summary>
public static class ApiKeyHasher
{
    public const int KeyByteLength = 32;

    public static string GenerateKey() =>
        "ares_" + Base64UrlEncode(RandomNumberGenerator.GetBytes(KeyByteLength));

    public static string Hash(string key, string? pepper = null)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(key);
        var material = string.IsNullOrEmpty(pepper) ? key : pepper + ":" + key;
        return Convert.ToHexStringLower(SHA256.HashData(Encoding.UTF8.GetBytes(material)));
    }

    public static bool Verify(string presentedKey, string expectedHash, string? pepper = null)
    {
        if (string.IsNullOrEmpty(presentedKey) || string.IsNullOrEmpty(expectedHash)) return false;
        var computed = Encoding.ASCII.GetBytes(Hash(presentedKey, pepper));
        var expected = Encoding.ASCII.GetBytes(expectedHash.ToLowerInvariant());
        if (computed.Length != expected.Length) return false;
        return CryptographicOperations.FixedTimeEquals(computed, expected);
    }

    /// <summary>Non-secret fingerprint for logs and key listings.</summary>
    public static string Fingerprint(string keyHash) =>
        keyHash.Length >= 12 ? keyHash[..12] : keyHash;

    private static string Base64UrlEncode(byte[] bytes) =>
        Convert.ToBase64String(bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_');
}
